interface User { id: number; name: string; email: string; }

// Derived — always in sync. Omit the id, make the rest optional.
type UpdateUser = Partial<Omit<User, 'id'>>;

function update(id: number, patch: UpdateUser) {
  console.log('updating', id, patch);
}

update(1, { name: 'Ada' });
update(1, { email: 'a@x.io' });

type MyPartial<T> = { [P in keyof T]?: T[P] };
type MyPick<T, K extends keyof T> = { [P in K]: T[P] };

interface User { id: number; name: string; email: string; }

const patch: MyPartial<User> = { name: 'Ada' };
const row: MyPick<User, 'id' | 'name'> = { id: 1, name: 'Ada' };

console.log(patch.name, row.id, row.name);
